    Props (p): nav, brand, links, search, landmarkLabel. *}
{var $v_nav = ($p['nav'] ?? null)}
{var $v_brand = ($p['brand'] ?? 'show')}
{var $v_links = ($p['links'] ?? 'hide')}
{var $v_search = ($p['search'] ?? 'show')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $c_10}
  {if ui_t(ui_eq($v_brand, 'show'))}
    {capture $c_2}
      {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'layers', 'Size' => 24]])|noescape}
      {capture $c_1}
        {=ui_text(ui_get($v_nav, ['brand']))}
      {/capture}
      {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'base', 'Weight' => 'bold', 'Class' => ui_s((ui_t(true) ? '' : 'sr-only'))], 'children' => $c_1])|noescape}
    {/capture}
    {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center', 'Class' => 'shrink-0', 'Attrs' => ui_attrs(['data-testid', 'brand'])], 'children' => $c_2])|noescape}
  {/if}
  {if ui_t(ui_eq($v_links, 'show'))}
    {capture $c_7}
      {capture $c_6}
        {foreach ui_l(ui_get($v_nav, ['links'])) as $v_l}
          {capture $c_5}
            {capture $c_4}
              {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_l, ['icon'])), 'Size' => 16]])|noescape}
              {capture $c_3}
                {=ui_text(ui_get($v_l, ['name']))}
              {/capture}
              {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => ui_s((ui_t(true) ? '' : 'sr-only'))], 'children' => $c_3])|noescape}
            {/capture}
            {=ui_include('ui/link/link.latte', ['p' => ['Href' => '#/', 'Variant' => 'default', 'Size' => 'sm', 'AriaCurrent' => ui_s((ui_t(ui_eq(ui_get($v_l, ['id']), ui_get($v_nav, ['current']))) ? 'page' : null)), 'Class' => ui_s(ui_cnv(['flex items-center gap-4 rounded py-2', (ui_t(true) ? 'px-4' : 'justify-center px-2'), (ui_t(ui_eq(ui_get($v_l, ['id']), ui_get($v_nav, ['current']))) ? 'bg-muted font-medium' : '')])), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_4])|noescape}
          {/capture}
          {=ui_include('ui/list/list-item.latte', ['p' => [], 'children' => $c_5])|noescape}
        {/foreach}
      {/capture}
      {=ui_include('ui/list/list.latte', ['p' => ['Class' => 'm-0 flex list-none items-center gap-2 p-0'], 'children' => $c_6])|noescape}
    {/capture}
    {=ui_include('blocks/nav-block.latte', ['p' => ['label' => (ui_t($v_landmarkLabel) ? ui_uniq(ui_tpl('{0}, {1}', [ui_get($v_nav, ['label']), $v_landmarkLabel])) : ui_get($v_nav, ['label'])), 'className' => ui_cnv(['hidden lg:block'])], 'children' => $c_7])|noescape}
  {/if}
  {if ui_t(ui_eq($v_search, 'show'))}
    {if ui_t(ui_eq($v_links, 'show'))}
      {capture $c_8}
        {=ui_include('blocks/search-palette.latte', ['p' => ['label' => ui_get($v_nav, ['search']), 'shortcut' => ui_get($v_nav, ['shortcut'])]])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Class' => 'ml-auto hidden w-64 shrink-0 xl:block'], 'children' => $c_8])|noescape}
    {else}
      {=ui_include('blocks/search-palette.latte', ['p' => ['label' => ui_get($v_nav, ['search']), 'shortcut' => ui_get($v_nav, ['shortcut'])]])|noescape}
    {/if}
  {/if}
  {capture $c_9}
    {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => 'bell', 'Size' => 20, 'Class' => 'text-muted-foreground']])|noescape}
    {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => ui_get($v_nav, ['userName']), 'ratio' => '1/1', 'className' => ui_cnv(['size-8 shrink-0 rounded-full'])]])|noescape}
  {/capture}
  {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Class' => ui_s((ui_t(ui_and([ui_eq($v_links, 'show'), ui_eq($v_search, 'show')])) ? 'shrink-0' : 'ml-auto shrink-0')), 'Attrs' => ui_attrs(['data-testid', 'user'])], 'children' => $c_9])|noescape}
{/capture}
{=ui_include('ui/block/block.latte', ['p' => ['Tag' => 'header', 'Class' => 'flex h-16 shrink-0 items-center gap-6 border-b border-border bg-background px-6', 'Attrs' => ui_attrs(['data-testid', 'topbar', 'aria-label', $v_landmarkLabel])], 'children' => $c_10])|noescape}
